"""ur — sira_c."""

T = {
"sira_151": ("نبی ﷺ کے کون سے چچا اسلام لائے اور مکہ میں ان کے سب سے مضبوط محافظوں میں سے ہوئے؟", ["حمزہ بن عبد المطلب", "ابو لہب", "ابو طالب", "العباس"], "حمزہ، نبی ﷺ کے چچا اور رضاعی بھائی، مکہ میں اسلام لائے اور «اللہ کا شیر» کہلائے۔"),
"sira_152": ("مکہ میں پہلے مسلمان کس کے گھر خفیہ طور پر جمع ہوتے تھے؟", ["ارقم کے گھر", "ابو بکر کے گھر", "خدیجہ کے گھر", "ابو طالب کے گھر"], "صفا پہاڑی پر ارقم بن ابی الارقم کا گھر اجتماع اور تعلیم کی پہلی جگہ تھی۔"),
"sira_153": ("مکہ میں اسلام لانے والے کون سے صحابی بعد میں یثرب کی طرف پہلے معلم بنا کر بھیجے گئے؟", ["مصعب بن عمیر", "بلال بن رباح", "خالد بن الولید", "ابو ہریرہ"], "مصعب بن عمیر، مکہ کے ایک معزز خاندان کے نوجوان، بیعتِ عقبہ کے بعد قرآن سکھانے کے لیے یثرب بھیجے گئے۔"),
"sira_154": ("سورۃ المدثر، جس سے علانیہ دعوت شروع ہوئی، کس حکم سے شروع ہوتی ہے؟", ["«اے چادر اوڑھنے والے! اٹھو اور ڈراؤ»", "«پڑھو، اپنے رب کے نام سے»", "«کافروں سے لڑو»", "«مدینہ ہجرت کرو»"], "«اے کپڑا اوڑھنے والے! اٹھو، پھر ڈراؤ۔»"),
"sira_155": ("کون سی آیت نے نبی ﷺ کو حکم دیا کہ جو حکم دیا گیا ہے اسے علانیہ بیان کریں؟", ["«پس جو حکم تمہیں دیا گیا ہے اسے علانیہ بیان کرو»", "«صبر کرو»", "«خفیہ تلاوت کرو»", "«کنارہ کش ہو جاؤ»"], "«پس جو حکم تمہیں دیا گیا ہے اسے علانیہ بیان کرو اور مشرکوں سے اعراض کرو۔»"),
"sira_156": ("قریش نے بنو ہاشم کے خلاف بائیکاٹ کا صحیفہ کہاں لٹکایا؟", ["کعبہ کے اندر", "شہر کے دروازے پر", "عکاظ کے بازار میں", "صفا پہاڑی پر"], "بائیکاٹ کا متن کعبہ کے اندر لٹکایا گیا، یہاں تک کہ معاہدہ ٹوٹ گیا اور صحیفہ ترک کر دیا گیا۔"),
"sira_157": ("طائف میں نکالے جانے کے بعد نبی ﷺ نے کس کے باغ میں پناہ لی اور انگور کا خوشہ پایا؟", ["عتبہ اور شیبہ کے باغ میں، جہاں غلام عداس نے ان کی خدمت کی", "طائف کے سردار کے گھر میں", "ایک گزرتے قافلے میں", "ایک لوہار کے گھر میں"], "زخمی حالت میں طائف سے نکالے جانے کے بعد انہوں نے ایک باغ میں پناہ لی، جہاں عداس نامی ایک عیسائی غلام نے انگور پیش کیے۔"),
"sira_158": ("کون سے صحابی، جو پہلے سخت مخالف تھے، اسلام لائے اور «حق و باطل میں فرق کرنے والا» کہلائے؟", ["عمر بن الخطاب", "ابو سفیان", "خالد بن الولید", "عمرو بن العاص"], "عمر بن الخطاب، جو ابتدا میں مخالف تھے، مکہ میں اسلام لائے اور انہیں الفاروق کا لقب ملا۔"),
"sira_159": ("مدینہ پہنچنے پر نبی ﷺ کس گھرانے کے ہاں ٹھہرے، جہاں ان کی اونٹنی بیٹھی؟", ["ابو ایوب انصاری کے ہاں", "سعد بن معاذ کے ہاں", "ابی بن کعب کے ہاں", "انس بن مالک کے ہاں"], "اونٹنی ابو ایوب انصاری کے گھر کے قریب بیٹھی، جنہوں نے آمد پر نبی ﷺ کی میزبانی کی۔"),
"sira_160": ("مدینہ کا وہ قبرستان کیا کہلاتا ہے جہاں بہت سے صحابہ مدفون ہیں؟", ["البقیع", "المعلاۃ", "الحجر", "القبا"], "بقیع الغرقد، مسجدِ نبوی ﷺ کے پہلو میں، مدینہ کا قبرستان ہے۔"),
"sira_161": ("قرآن کس مسجد کو «پہلے ہی دن سے تقویٰ پر بنیاد رکھی گئی» بیان کرتا ہے؟", ["مسجدِ قبا", "مسجدِ حرام", "مسجدِ اقصیٰ", "مسجدِ کوفہ"], "«وہ مسجد جس کی بنیاد پہلے ہی دن سے تقویٰ پر رکھی گئی، زیادہ حق دار ہے کہ تم اس میں کھڑے ہو۔»"),
"sira_162": ("تحویلِ قبلہ کا حکم نازل ہوا تو نبی ﷺ کس مسجد میں نماز پڑھ رہے تھے؟", ["مسجدِ قبلتین (دو قبلوں والی مسجد)", "مسجدِ قبا", "مسجدِ حرام", "مسجدِ اقصیٰ"], "حکم نماز کے دوران آیا؛ نمازیوں نے کعبہ کی طرف رخ کر لیا، اسی لیے اس کا نام «دو قبلوں والی مسجد» پڑا۔"),
"sira_163": ("ہجرت کے دوسرے سال مسلمانوں پر کون سی عبادت فرض کی گئی؟", ["ماہِ رمضان کے روزے", "حج", "قیام اللیل", "طائف کا سفر"], "رمضان کے روزے مدینہ میں، ہجرت کے دوسرے سال فرض کیے گئے۔"),
"sira_164": ("کس صحابی نے خواب میں اذان کے کلمات دیکھے، جنہیں نبی ﷺ نے اختیار فرمایا؟", ["عبد اللہ بن زید", "بلال بن رباح", "ابو بکر", "معاذ بن جبل"], "عبد اللہ بن زید نے اذان کا خواب بیان کیا؛ نبی ﷺ نے اسے پسند فرمایا اور بلال کو اذان دینے کا حکم دیا۔"),
"sira_165": ("بدر میں نبی ﷺ کے پھینکے ہوئے مٹی کے مٹھی بھر کے بارے میں قرآن کیا کہتا ہے؟", ["«جب تم نے پھینکا تو تم نے نہیں پھینکا بلکہ اللہ نے پھینکا»", "«تم نے ٹھیک نشانہ لگایا»", "«ہوا اسے لے گئی»", "«فرشتوں نے پھینکا»"], "«اور جب تم نے پھینکا تو تم نے نہیں پھینکا بلکہ اللہ نے پھینکا۔»"),
"sira_166": ("بدر کی طرف نکلتے وقت بعض مومنوں کی حالت کو قرآن کیسے بیان کرتا ہے؟", ["وہ اس بارے میں جھگڑ رہے تھے گویا موت کی طرف ہانکے جا رہے ہوں", "سب پرجوش تھے", "انہوں نے نکلنے سے انکار کیا", "انہوں نے مہلت مانگی"], "«وہ حق کے بارے میں تم سے جھگڑتے تھے بعد اس کے کہ وہ واضح ہو چکا، گویا وہ موت کی طرف ہانکے جا رہے ہوں۔»"),
"sira_167": ("قرآن مومنوں کو فتح سے پہلے کی حالت کیسے یاد دلاتا ہے؟", ["وہ تھوڑے اور زمین میں کمزور تھے، پھر اللہ نے انہیں ٹھکانا دیا اور مدد کی", "وہ مالدار تھے", "وہ کثیر تھے", "وہ پہلے ہی حکومت کرتے تھے"], "«اور یاد کرو جب تم تھوڑے تھے، زمین میں کمزور سمجھے جاتے تھے… پھر اس نے تمہیں ٹھکانا دیا اور اپنی مدد سے تمہیں قوت دی۔»"),
"sira_168": ("بدر میں کس صحابی نے مشورہ دیا کہ لشکر کو دشمن کے قریب ترین کنویں پر منتقل کیا جائے؟", ["حباب بن المنذر", "سعد بن معاذ", "المقداد", "الزبیر"], "حباب بن المنذر نے پوچھا کہ یہ جگہ وحی ہے یا رائے؛ جب بتایا گیا کہ رائے ہے تو انہوں نے کنویں کی طرف بڑھنے کا مشورہ دیا، اور نبی ﷺ نے قبول فرمایا۔"),
"sira_169": ("جنگِ بدر جس چشمے پر ہوئی اس کا نام کیا تھا؟", ["بدر، قافلوں کے راستے پر ایک کنواں", "زمزم", "قبا", "الحدیبیہ"], "بدر مکہ اور شام کے درمیان قافلوں کے راستے پر پانی کی ایک جگہ تھی؛ جنگ کا نام اسی سے پڑا۔"),
"sira_170": ("بدر کے بعد قیدیوں کے بارے میں کون سا معاملہ وحی کے ذریعے بیان ہوا؟", ["قیدیوں کے لیے قبول کیا گیا فدیہ", "پانی کی تقسیم", "پڑاؤ کا انتخاب", "واپسی کی تاریخ"], "یہ اقتباس قیدیوں اور فدیے کا ذکر کرتا ہے، پھر جو کچھ لیا گیا اسے حلال و پاکیزہ قرار دیتا ہے۔"),
"sira_171": ("سورۃ آل عمران کے مطابق احد میں ابتدائی کامیابی کے بعد حالات کس چیز نے پلٹے؟", ["نافرمانی اور دیے گئے حکم کے بارے میں اختلاف", "دشمن کی تعداد", "گرمی", "پانی کی کمی"], "«…یہاں تک کہ تم نے ہمت ہاری اور حکم کے بارے میں جھگڑا کیا اور نافرمانی کی۔»"),
"sira_172": ("اللہ کی راہ میں مارے جانے والوں کے بارے میں قرآن کیا کہتا ہے؟", ["انہیں مردہ نہ سمجھو: وہ اپنے رب کے پاس زندہ ہیں", "وہ قیامت تک سوتے ہیں", "وہ لوٹ آتے ہیں", "وہ بھلا دیے جاتے ہیں"], "«اور جو اللہ کی راہ میں مارے گئے انہیں ہرگز مردہ نہ سمجھو۔ بلکہ وہ اپنے رب کے پاس زندہ ہیں، رزق دیے جاتے ہیں۔»"),
"sira_173": ("احد میں نبی ﷺ نے تیر اندازوں کو کس پہاڑی پر متعین کیا؟", ["جبل الرماۃ (تیر اندازوں کی پہاڑی)", "صفا پہاڑی", "جبلِ ثور", "جبلِ حرا"], "پچاس تیر انداز ایک پہاڑی پر متعین کیے گئے جو بعد میں «تیر اندازوں کی پہاڑی» کہلائی، اور انہیں اسے نہ چھوڑنے کا حکم تھا۔"),
"sira_174": ("سورۃ الاحزاب مدینہ کے محاصرے کی آزمائش کو کیسے بیان کرتی ہے؟", ["نگاہیں پھر گئیں، دل حلق تک آ گئے", "شہر گر گیا", "صرف کھانا ختم ہوا", "آسمان تاریک ہو گیا"], "«جب وہ تم پر تمہارے اوپر سے اور تمہارے نیچے سے آ پڑے، اور جب نگاہیں پھر گئیں اور دل حلق تک آ گئے۔»"),
"sira_175": ("قرآن جنگِ خندق کے انجام کو کیسے بیان کرتا ہے؟", ["اللہ نے احزاب کو ان کے غصے سمیت لوٹا دیا، انہوں نے کوئی بھلائی نہ پائی", "ایک طویل معرکہ", "ایک صلح نامہ", "مسلمانوں کی پسپائی"], "«اور اللہ نے کافروں کو ان کے غصے سمیت لوٹا دیا، انہوں نے کوئی بھلائی نہ پائی۔ اور اللہ مومنوں کے لیے لڑائی میں کافی ہو گیا۔»"),
"sira_176": ("حدیبیہ، مشہور معاہدے کی جگہ، کہاں واقع ہے؟", ["حرم کی سرحد پر، مکہ کے مغرب میں", "مدینہ کے قریب", "یمن میں", "شام میں"], "حدیبیہ مکہ کے حرم کی سرحد پر واقع ایک جگہ ہے، جہاں معاہدہ طے پایا۔"),
"sira_177": ("حدیبیہ کے بعد قرآن نبی ﷺ کے کس خواب کی تصدیق کرتا ہے؟", ["کہ وہ امن کے ساتھ مسجدِ حرام میں داخل ہوں گے، سر منڈوائے یا بال کتروائے ہوئے", "کہ وہ خیبر میں فتح پائیں گے", "کہ وہ ایک شہر بسائیں گے", "کہ وہ شام کا سفر کریں گے"], "«یقیناً اللہ نے اپنے رسول کو سچا خواب دکھایا: تم ضرور مسجدِ حرام میں امن کے ساتھ داخل ہو گے۔»"),
"sira_178": ("سورۃ الفتح مکہ میں ہاتھ روکے جانے کے بارے میں کیا یاد دلاتی ہے؟", ["اللہ نے ان کے ہاتھ تم سے اور تمہارے ہاتھ ان سے مکہ کے اندر روک دیے", "اس نے لڑائی کا حکم دیا", "اس نے راستے بند کر دیے", "اس نے آندھی بھیجی"], "«اور وہی ہے جس نے مکہ کی وادی میں ان کے ہاتھ تم سے اور تمہارے ہاتھ ان سے روک دیے، بعد اس کے کہ اس نے تمہیں ان پر غلبہ دیا۔»"),
"sira_179": ("خیبر کا غزوہ ہجرت کے کس سال ہوا؟", ["ساتویں", "دوسرے", "پانچویں", "دسویں"], "خیبر 7 ہجری میں ہوا، صلحِ حدیبیہ کے اگلے سال۔"),
"sira_180": ("حدیبیہ کے اگلے سال معاہدے کی شرائط کے مطابق ادا کیا گیا عمرہ کیا کہلاتا ہے؟", ["عمرۃ القضاء", "حجۃ الوداع", "عمرۃ الجعرانہ", "الحج الاکبر"], "معاہدے میں طے پایا کہ مسلمان اگلے سال لوٹیں گے؛ اسی عمرے کو عمرۃ القضاء کہا جاتا ہے۔"),
"sira_181": ("کس حکمران نے نبی ﷺ کا خط پا کر اسے پھاڑ ڈالا؟", ["فارس کے بادشاہ (کسریٰ) نے", "حبشہ کے نجاشی نے", "بحرین کے گورنر نے", "یمن کے بادشاہ نے"], "نبی ﷺ نے پڑوسی حکمرانوں کو خطوط بھیجے؛ فارس کے بادشاہ کے نام خط پھاڑ دیا گیا۔"),
"sira_182": ("کس صحابی کو نبی ﷺ کا خط لے کر حبشہ کے نجاشی اور دیگر حکمرانوں کی طرف بھیجا گیا؟", ["عمرو بن امیہ الضمری", "ابو ہریرہ", "انس بن مالک", "ابی بن کعب"], "قاصد صحابہ میں سے چنے گئے؛ عمرو بن امیہ الضمری نجاشی کی طرف بھیجے گئے۔"),
"sira_183": ("خیبر مدینہ سے کس سمت واقع ہے؟", ["شمال کی طرف", "جنوب کی طرف", "مشرق کی طرف", "مغرب کی طرف، سمندر پر"], "خیبر مدینہ کے شمال میں، شام کے راستے پر ایک قلعہ بند نخلستان ہے۔"),
"sira_184": ("فتحِ مکہ کے دن ابو سفیان کا گھر کیا بن گیا؟", ["جو اس میں داخل ہو اس کے لیے امن کی جگہ", "ایک قید خانہ", "ایک گودام", "ایک مسجد"], "نبی ﷺ نے اعلان فرمایا کہ جو مسجدِ حرام میں داخل ہو، اپنے گھر میں رہے، یا ابو سفیان کے گھر میں داخل ہو، وہ محفوظ ہے۔"),
"sira_185": ("کون سا سال «عام الفتح» (فتح کا سال) کہلاتا ہے؟", ["8 ہجری", "6 ہجری", "10 ہجری", "2 ہجری"], "مکہ 8 ہجری میں فتح ہوا، وہ سال جو «فتح کا سال» کہلاتا ہے۔"),
"sira_186": ("فتحِ مکہ کے فوراً بعد ہوازن کے قبائل کے خلاف کون سا غزوہ ہوا؟", ["حنین", "بدر", "احد", "خیبر"], "حنین فتح کے کچھ ہی بعد، مکہ اور طائف کے درمیان ایک وادی میں ہوا۔"),
"sira_187": ("حنین میں گھبراہٹ کے بعد اللہ نے اپنے رسول ﷺ اور مومنوں پر کیا نازل کیا؟", ["اپنی سکینت، اور ایسے لشکر جو انہیں نظر نہ آئے", "بارش", "ایک ہوا", "ایک سوار دستہ"], "«پھر اللہ نے اپنی سکینت اپنے رسول پر اور مومنوں پر نازل کی، اور ایسے لشکر اتارے جو تم نے نہ دیکھے۔»"),
"sira_188": ("حنین کے بعد مسلمان لشکر کس شہر کی طرف بڑھا؟", ["طائف", "خیبر", "تبوک", "صنعاء"], "حنین کے بعد مسلمانوں نے طائف کا محاصرہ کیا، جس کے لوگ اندر بند ہو گئے تھے۔"),
"sira_189": ("قرآن کس غزوے کو «ساعۃ العسرۃ» (تنگی کی گھڑی) کہتا ہے؟", ["تبوک", "بدر", "خیبر", "حنین"], "«اللہ نے نبی، مہاجرین اور انصار کی توبہ قبول کی جنہوں نے تنگی کی گھڑی میں ان کی پیروی کی۔»"),
"sira_190": ("تبوک میں پیچھے رہ جانے والے تین صحابہ کے بارے میں قرآن کیا کہتا ہے، ان کی معافی سے پہلے؟", ["زمین اپنی وسعت کے باوجود ان پر تنگ ہو گئی، پھر اللہ نے ان کی توبہ قبول کی", "انہیں جلاوطن کیا گیا", "وہ یمن چلے گئے", "وہ بھلا دیے گئے"], "«اور وہ تین جو پیچھے رہ گئے، یہاں تک کہ زمین اپنی وسعت کے باوجود ان پر تنگ ہو گئی… پھر اس نے ان کی توبہ قبول کی۔»"),
"sira_191": ("آخری بڑے غزوے کا ہدف تبوک کس سمت واقع ہے؟", ["شمال میں، شام کی سرحد کی طرف", "جنوب میں، یمن کی طرف", "مشرق میں، عراق کی طرف", "مغرب میں، بحرِ احمر پر"], "تبوک مدینہ کے شمال میں، شام کے راستے پر ہے؛ یہ نبی ﷺ کا آخری بڑا غزوہ تھا۔"),
"sira_192": ("کس صحابی نے تبوک کے لشکر کا بڑا حصہ اپنے مال سے تیار کیا؟", ["عثمان بن عفان", "سعد بن ابی وقاص", "طلحہ بن عبید اللہ", "ابو ذر"], "عثمان بن عفان نے «جیش العسرۃ» کے سامان کا بڑا حصہ فراہم کیا۔"),
"sira_193": ("اللہ کی راہ میں سب سے پہلے تیر کس صحابی نے چلایا؟", ["سعد بن ابی وقاص", "الزبیر بن العوام", "طلحہ بن عبید اللہ", "ابو عبیدہ"], "سعد بن ابی وقاص، جو ابتدائی مسلمانوں میں سے تھے، اللہ کی راہ میں پہلا تیر چلانے والے کے طور پر معروف ہیں۔"),
"sira_194": ("کون سے صحابی «رسول اللہ ﷺ کے حواری» کہلاتے ہیں؟", ["الزبیر بن العوام", "ابو ہریرہ", "سلمان الفارسی", "بلال"], "الزبیر بن العوام، نبی ﷺ کے پھوپھی زاد، ان کے حواری یعنی قریبی مددگار کہلائے۔"),
"sira_195": ("منافقین کے بارے میں کس صحابی کو راز سونپا گیا، اسی لیے وہ «رازداں» کہلائے؟", ["حذیفہ بن الیمان", "ابو موسیٰ الاشعری", "عمار بن یاسر", "ابو الدرداء"], "حذیفہ بن الیمان «صاحب السر» کے طور پر معروف ہیں، جنہیں نبی ﷺ نے منافقین کے بارے میں بتایا۔"),
"sira_196": ("خندق کا مشورہ دینے والے سلمان، جو «الفارسی» کہلاتے ہیں، کہاں کے تھے؟", ["فارس کے", "یمن کے", "حبشہ کے", "روم کے"], "سلمان، جو فارسی الاصل تھے، مدینہ میں نبی ﷺ کے پاس پہنچنے سے پہلے مدتوں حق کی تلاش میں رہے۔"),
"sira_197": ("کس خاتون نے، جو انس بن مالک کی والدہ تھیں، اپنے بیٹے کو نبی ﷺ کی خدمت کے لیے پیش کیا؟", ["ام سلیم", "ام سلمہ", "ام ایمن", "ام حبیبہ"], "انصار کی ام سلیم نے مدینہ آمد پر اپنے بیٹے انس کو نبی ﷺ کی خدمت کے لیے پیش کیا۔"),
"sira_198": ("نبی ﷺ کی کون سی زوجہ اپنے وسیع علم اور کثرتِ روایت کے لیے معروف ہیں؟", ["عائشہ", "سودہ", "جویریہ", "میمونہ"], "عائشہ، ابو بکر کی صاحبزادی، حدیث کے سب سے بڑے راویوں میں سے ہیں اور دینی علم میں مرجع ہیں۔"),
"sira_199": ("نبی ﷺ کی کون سی زوجہ ان کی پھوپھی زاد تھیں، اور جن کے نکاح کا ذکر سورۃ الاحزاب میں ہے؟", ["زینب بنت جحش", "حفصہ", "ام سلمہ", "صفیہ"], "زینب بنت جحش سے نکاح کا ذکر سورۃ الاحزاب (33:37) میں ہے۔"),
"sira_200": ("نبی ﷺ کی کس زوجہ نے وہ مشورہ دیا جس سے حدیبیہ کی گرہ کھلی؟", ["ام سلمہ", "عائشہ", "حفصہ", "زینب بنت جحش"], "ام سلمہ نے نبی ﷺ کو مشورہ دیا کہ خود باہر نکل کر قربانی کریں اور سر منڈوائیں: صحابہ نے فوراً پیروی کی۔"),
"sira_201": ("نبی ﷺ کا پورا نام، دادا تک، کیا ہے؟", ["محمد بن عبد اللہ بن عبد المطلب", "محمد بن ابی طالب", "محمد بن العباس", "محمد بن ہاشم"], "وہ محمد ہیں، عبد اللہ کے بیٹے، عبد المطلب کے پوتے، قبیلۂ قریش سے۔"),
"sira_202": ("نبی ﷺ کا کون سا دوسرا نام، جو قرآن میں عیسیٰ نے بیان کیا، «سب سے زیادہ تعریف کیا گیا» کے معنی میں ہے؟", ["احمد", "المصطفیٰ", "الامین", "ابو القاسم"], "عیسیٰ نے اپنے بعد آنے والے ایک رسول کی خبر دی «جس کا نام احمد ہے» (قرآن 61:6)۔"),
"sira_203": ("قرآن نبی ﷺ پر کتنے عرصے میں نازل ہوا؟", ["تقریباً تئیس سال", "دس سال", "چالیس سال", "ایک ہی رات"], "وحی کا سلسلہ تقریباً تئیس سال پر محیط رہا: تیرہ سال مکہ میں اور دس سال مدینہ میں۔"),
"sira_204": ("آزاد بالغ مردوں میں سب سے پہلے اسلام لانے والے کون سے صحابی تھے؟", ["ابو بکر صدیق", "عمر بن الخطاب", "عثمان بن عفان", "سعد بن ابی وقاص"], "آزاد بالغ مردوں میں ابو بکر سب سے پہلے نبی ﷺ کی دعوت پر لبیک کہنے والے تھے۔"),
"sira_205": ("سب سے پہلے اسلام لانے والا بچہ کون تھا؟", ["علی بن ابی طالب", "انس بن مالک", "اسامہ بن زید", "عبد اللہ بن عمر"], "علی بن ابی طالب، جو نبی ﷺ کے گھر میں پرورش پائے، بچوں میں سب سے پہلے ایمان لائے۔"),
"sira_206": ("نبی ﷺ کے کون سے آزاد کردہ غلام موالی میں سب سے پہلے اسلام لائے؟", ["زید بن حارثہ", "بلال بن رباح", "صہیب الرومی", "سلمان الفارسی"], "زید بن حارثہ، جنہیں نبی ﷺ نے آزاد کر کے بیٹے کی طرح پالا، موالی میں سب سے پہلے ایمان لائے۔"),
"sira_207": ("کس آیت نے متبنّیٰ کے نسبی حکم کو ختم کیا، یہ بیان کر کے کہ نبی ﷺ ان کے مردوں میں سے کسی کے باپ نہیں؟", ["«محمد تمہارے مردوں میں سے کسی کے باپ نہیں، بلکہ اللہ کے رسول اور خاتم النبیین ہیں»", "«انہیں ان کے باپوں کی نسبت سے پکارو»", "«خونی رشتے مقدم ہیں»", "«متبنّیٰ نہ بناؤ»"], "«محمد تمہارے مردوں میں سے کسی کے باپ نہیں، بلکہ وہ اللہ کے رسول اور خاتم النبیین ہیں۔»"),
"sira_208": ("مدینہ میں مقرر کی گئی اجتماعی نماز کے لیے مسلمان ہفتے کے کس دن جمع ہوتے ہیں؟", ["جمعہ", "ہفتہ", "اتوار", "پیر"], "نمازِ جمعہ مدینہ میں مقرر ہوئی اور ہر ہفتے امت کو جمع کرتی ہے۔"),
"sira_209": ("نبی ﷺ کے مرضِ وفات میں ان کے اپنے حکم سے کس صحابی نے نماز پڑھائی؟", ["ابو بکر صدیق", "عمر بن الخطاب", "علی بن ابی طالب", "بلال"], "نبی ﷺ نے حکم دیا کہ ان کی بیماری میں ابو بکر نماز پڑھائیں؛ صحابہ نے اسے ایک اشارہ سمجھا۔"),
"sira_210": ("کون سے خلیفہ فجر کی نماز پڑھاتے ہوئے حملے کا نشانہ بنے؟", ["عمر بن الخطاب", "ابو بکر", "علی بن ابی طالب", "معاویہ"], "عمر بن الخطاب مدینہ میں نمازِ فجر کے دوران زخمی کیے گئے اور زخموں سے شہید ہوئے۔"),
"sira_211": ("ابو بکر کی خلافت کتنے عرصے رہی؟", ["تقریباً دو سال", "دس سال", "بیس سال", "تیس سال"], "ابو بکر نے اپنی وفات تک تقریباً دو سال حکومت کی، اور عمر ان کے جانشین ہوئے۔"),
"sira_212": ("اپنی خلافت کے آغاز میں ابو بکر کو کس تحریک کا سامنا کرنا پڑا؟", ["زکوٰۃ سے انکار اور بعض قبائل کا ارتداد", "فارس کی طرف سے حملہ", "قحط", "مدینہ میں بغاوت"], "پہلی خلافت کا آغاز جنگِ ردہ سے ہوا، ان قبائل کے خلاف جنہوں نے زکوٰۃ سے انکار کیا یا اسلام چھوڑ دیا۔"),
"sira_213": ("عمر بن الخطاب نے امت کے سربراہ کے طور پر کون سا لقب اختیار کیا؟", ["امیر المومنین", "سلطان", "ملک", "امام الحرمین"], "امیر المومنین کا لقب عمر کے دور میں مقرر ہوا اور بعد کے خلفاء نے اسے اختیار کیا۔"),
"sira_214": ("بیت المقدس کی کون سی مسجد مسلمانوں کا پہلا قبلہ تھی؟", ["مسجدِ اقصیٰ", "مسجدِ قبا", "مسجدِ نبوی ﷺ", "مسجدِ حرام"], "مسلمان پہلے بیت المقدس کی طرف رخ کر کے نماز پڑھتے تھے، بعد میں قبلہ کعبہ کی طرف مقرر ہوا۔"),
"sira_215": ("کون سی تین مسجدیں ہیں جن کی طرف خصوصی طور پر سفر کی ترغیب دی گئی ہے؟", ["مسجدِ حرام، مسجدِ نبوی ﷺ اور مسجدِ اقصیٰ", "قبا، اقصیٰ اور کوفہ", "مسجدِ حرام، قبا اور دمشق", "اقصیٰ، کوفہ اور بصرہ"], "تین مسجدوں کی طرف خصوصی طور پر سفر کی ترغیب ہے: مسجدِ حرام، مسجدِ نبوی ﷺ اور مسجدِ اقصیٰ۔"),
"sira_216": ("نبی ﷺ نے یومِ عرفہ کو خطبۂ حجۃ الوداع کہاں دیا؟", ["وادیِ عُرَنہ میں، جبلِ عرفات کے پاس", "منیٰ میں", "کعبہ کے سامنے", "مزدلفہ میں"], "خطبۂ وداع یومِ عرفہ کو، جبلِ عرفات کے دامن میں وادیِ عُرَنہ میں دیا گیا۔"),
"sira_217": ("نبی ﷺ نے خطبۂ وداع میں کس چیز کو حرام قرار دیا؟", ["ہر شخص کا خون، مال اور عزت", "تجارتی راستے", "مدینہ کے کنویں", "کھجور کے باغات"], "انہوں نے مسلمانوں کے خون، مال اور عزت کو حرمت والا قرار دیا، جیسے وہ دن، وہ مہینہ اور وہ شہر حرمت والے ہیں۔"),
"sira_218": ("نبی ﷺ نے خطبۂ وداع میں اپنی امت کے لیے کیا چھوڑا، تاکہ وہ گمراہ نہ ہو؟", ["اللہ کی کتاب", "ایک خزانہ", "ایک لشکر", "ایک نقشہ"], "انہوں نے یاد دلایا کہ وہ ان میں وہ چیز چھوڑے جا رہے ہیں جسے تھامے رکھیں تو گمراہ نہ ہوں گے: اللہ کی کتاب۔"),
"sira_219": ("اسلامی تقویم کا کون سا مہینہ نبی ﷺ کے حجۃ الوداع کی نشاندہی کرتا ہے؟", ["ذوالحجہ", "رمضان", "محرم", "رجب"], "حجۃ الوداع 10 ہجری کے ذوالحجہ میں ادا ہوا۔"),
"sira_220": ("نبی ﷺ کی وفات کے بعد ان کے جسدِ مبارک کو کس نے غسل دیا اور کفن پہنایا؟", ["ان کے اہلِ خانہ نے، جن میں علی اور العباس تھے", "صرف انصار نے", "بلال اور انس نے", "اہلِ قبا نے"], "ان کے اپنے گھر والوں نے یہ فریضہ انجام دیا، جن میں علی بن ابی طالب اور ان کے چچا العباس شامل تھے۔"),
"sira_221": ("نبی ﷺ کی وفات ہجری سال کے کس مہینے میں ہوئی؟", ["ربیع الاول", "رمضان", "شوال", "ذوالقعدہ"], "نبی ﷺ کی وفات مدینہ میں ربیع الاول کے مہینے میں، 11 ہجری میں ہوئی۔"),
"sira_222": ("ابو بکر نے لوگوں کو یہ یاد دلانے کے لیے کون سی آیت پڑھی کہ نبی ﷺ بشر تھے؟", ["«محمد صرف ایک رسول ہیں؛ ان سے پہلے بھی رسول گزر چکے ہیں»", "«ہم نے تمہیں رحمت بنا کر بھیجا»", "«تم عظیم اخلاق پر ہو»", "«جب اللہ کی مدد آ جائے»"], "«اور محمد صرف ایک رسول ہیں۔ ان سے پہلے بھی رسول گزر چکے ہیں۔ تو کیا اگر وہ فوت ہو جائیں یا قتل کر دیے جائیں تو تم الٹے پاؤں پھر جاؤ گے؟»"),
"sira_223": ("کون سے صحابی سب سے زیادہ احادیث یاد کرنے کے لیے معروف ہیں؟", ["ابو ہریرہ", "انس بن مالک", "جابر بن عبد اللہ", "ابو سعید الخدری"], "ابو ہریرہ نے نبی ﷺ کے آخری سال ان کے ساتھ گزارے اور سب سے زیادہ حدیثیں روایت کرنے والے بنے۔"),
"sira_224": ("کون سے صحابی، جو نبی ﷺ کے چچا زاد تھے، تفسیرِ قرآن کے بڑے امام بنے؟", ["عبد اللہ بن عباس", "عبد اللہ بن عمر", "عبد اللہ بن مسعود", "عبد اللہ بن الزبیر"], "عبد اللہ بن عباس، جن کے لیے نبی ﷺ نے کتاب کی سمجھ کی دعا کی، «ترجمان القرآن» بنے۔"),
"sira_225": ("کس صحابی کو نبی ﷺ نے یمن کا والی اور قاضی بنا کر بھیجا، اور جو کم عمری میں شام میں وفات پا گئے؟", ["معاذ بن جبل", "ابو عبیدہ بن الجراح", "عمرو بن العاص", "خالد بن الولید"], "معاذ بن جبل، صحابہ میں ایک عالم، یمن بھیجے گئے اور بعد میں کم عمری ہی میں شام میں وفات پا گئے۔"),
"sira_226": ("صفا اور مروہ کی دو پہاڑیوں کے درمیان کون سی وادی ہے، جہاں حج میں سعی کی جاتی ہے؟", ["وادیِ مکہ، کعبہ کے گرد", "وادیِ عُرَنہ", "وادیِ منیٰ", "وادیِ بدر"], "صفا اور مروہ وادیِ مکہ میں دو چھوٹی پہاڑیاں ہیں، جو آج مسجدِ حرام کے اندر شامل ہیں۔"),
"sira_227": ("نبی ﷺ کی آمد سے پہلے مدینہ کے کون سے دو بڑے عرب قبیلے آپس میں برسرِ پیکار تھے؟", ["اوس اور خزرج", "قریش اور ہوازن", "ثقیف اور کنانہ", "تمیم اور بکر"], "اوس اور خزرج، جو مدتوں سے دشمن تھے، نبی ﷺ کی آمد کے بعد مل کر انصار بنے۔"),
"sira_228": ("کون سی آیت انصار کو یاد دلاتی ہے کہ وہ دشمن تھے اور اللہ نے ان کے دلوں کو جوڑ دیا؟", ["«تم دشمن تھے اور اس نے تمہارے دلوں کو جوڑ دیا»", "«تم غریب تھے»", "«تم تھوڑے تھے»", "«تم بھٹکے ہوئے تھے»"], "«اور اپنے اوپر اللہ کی نعمت یاد کرو: جب تم دشمن تھے تو اس نے تمہارے دلوں کو جوڑ دیا، پس تم اس کی نعمت سے بھائی بھائی ہو گئے۔»"),
"sira_229": ("مہاجرین کے استقبال میں قرآن انصار کی کیسے تعریف کرتا ہے؟", ["وہ اپنی ضرورت کے باوجود دوسروں کو اپنے اوپر ترجیح دیتے ہیں", "انہوں نے انہیں زمین بیچی", "انہوں نے انہیں قرض دیا", "انہوں نے انہیں شہر سے باہر ٹھہرایا"], "«اور وہ اپنے اوپر دوسروں کو ترجیح دیتے ہیں، اگرچہ خود محتاج ہوں۔ اور جو اپنے نفس کے بخل سے بچا لیا گیا، تو وہی کامیاب ہیں۔»"),
"sira_230": ("نبی ﷺ کے اقوال، افعال اور تقریرات کے مجموعے کو کیا کہتے ہیں؟", ["سنت", "قرآن", "سیرت", "تفسیر"], "سنت وہ ہے جو نبی ﷺ نے کہا، کیا یا جس کی تصدیق فرمائی؛ سیرت ان کی زندگی کا بیان ہے۔"),
"sira_231": ("صحابہ کے بعد آنے والی نسل کو کیا کہتے ہیں؟", ["تابعین", "انصار", "مہاجرین", "قراء"], "تابعین وہ ہیں جنہوں نے صحابہ کو دیکھا لیکن نبی ﷺ کو نہ دیکھا۔"),
"sira_232": ("حدیث کے راویوں کے سلسلے کو کیا کہتے ہیں؟", ["اسناد", "متن", "تفسیر", "تجوید"], "اسناد نقل کا سلسلہ ہے؛ متن خود حدیث کا نص ہے۔"),
"sira_233": ("حدیث کے کون سے دو مجموعے سب سے زیادہ محتاط سمجھے جاتے ہیں، جو «صحیحین» کہلاتے ہیں؟", ["صحیح البخاری اور صحیح مسلم", "سنن ابی داؤد اور ترمذی", "موطأ اور مسند", "سنن نسائی اور ابن ماجہ"], "صحیح البخاری اور صحیح مسلم کو مل کر «الصحیحان» کہا جاتا ہے۔"),
"sira_234": ("نبی ﷺ کی مسجد اور ان کی قبرِ مبارک کس شہر میں ہیں؟", ["مدینہ", "مکہ", "بیت المقدس", "طائف"], "نبی ﷺ کی مسجد اور ان کی قبرِ مبارک مدینہ میں ہیں، ہجرت کے شہر میں۔"),
"sira_235": ("مدینہ کو کون سا لقب حاصل ہے، جو اس سے منسوب نور کی طرف اشارہ کرتا ہے؟", ["المدینۃ المنورہ", "ام القریٰ", "دار السلام", "المدائن"], "مدینہ کو المنورہ کہا جاتا ہے؛ مکہ کو اپنی جگہ المکرمہ کہا جاتا ہے۔"),
"sira_236": ("قرآن مکہ کو «بستیوں کی ماں» کے طور پر کیا نام دیتا ہے؟", ["ام القریٰ", "المدینہ", "البلد الامین", "بکہ"], "«…تاکہ تم ام القریٰ اور اس کے گرد رہنے والوں کو ڈراؤ۔»"),
"sira_237": ("نبی ﷺ کی پہلی زوجہ خدیجہ کا پیشہ کیا تھا؟", ["تاجرہ", "طبیبہ", "شاعرہ", "بُنکر"], "خدیجہ بنت خویلد مکہ کی ایک معزز تاجرہ تھیں، جنہوں نے اپنا قافلہ نوجوان محمد ﷺ کے سپرد کیا۔"),
"sira_238": ("نبی ﷺ کتنے عرصے تک صرف خدیجہ کے ساتھ نکاح میں رہے؟", ["ان کی وفات تک؛ ان کی زندگی میں کسی اور سے نکاح نہ کیا", "دو سال", "پانچ سال", "انہوں نے فوراً دوسری شادیاں کیں"], "خدیجہ کی زندگی میں نبی ﷺ نے کسی اور خاتون سے نکاح نہ کیا؛ بعد کے نکاح ان کی وفات کے بعد ہوئے۔"),
"sira_239": ("نبی ﷺ کے اس چچا کا نام کیا ہے جنہوں نے اسلام لائے بغیر ان کی حفاظت کی؟", ["ابو طالب", "حمزہ", "العباس", "ابو لہب"], "ابو طالب، علی کے والد، اپنی وفات تک اپنے بھتیجے کو قریش سے بچاتے رہے۔"),
"sira_240": ("نبی ﷺ کے کون سے چچا بدر میں قید ہوئے، بعد میں اسلام لائے؟", ["العباس بن عبد المطلب", "ابو طالب", "حمزہ", "الزبیر بن عبد المطلب"], "العباس، نبی ﷺ کے چچا اور بنو عباس کے جدِ اعلیٰ، بدر میں قید ہوئے اور بعد میں اسلام لائے۔"),
"sira_241": ("جنگِ بدر میں شریک صحابہ کو کیا کہا جاتا ہے؟", ["بدریون (اہلِ بدر)", "انصار", "مہاجرین", "اہلِ احد"], "بدر میں حاضر صحابہ بدریون کے نام سے معروف ہیں، اور یہ فضیلت انہی کے ساتھ خاص ہے۔"),
"sira_242": ("قرآن مالِ غنیمت کا کتنا حصہ اللہ، رسول، قرابت داروں، یتیموں، مسکینوں اور مسافر کے لیے مقرر کرتا ہے؟", ["پانچواں حصہ", "آدھا", "دسواں حصہ", "تیسرا حصہ"], "«اور جان لو کہ جو کچھ تم غنیمت میں لو، اس کا پانچواں حصہ اللہ اور رسول کے لیے، اور قرابت داروں، یتیموں، مسکینوں اور مسافر کے لیے ہے۔»"),
"sira_243": ("کون سی آیت، جو اکثر خطبۂ وداع کے ساتھ پیش کی جاتی ہے، اللہ کے نزدیک اقوام کی برابری کی بنیاد رکھتی ہے؟", ["«تم میں سب سے معزز اللہ کے نزدیک وہ ہے جو سب سے زیادہ متقی ہے»", "«لوگ ایک باپ کی اولاد ہیں»", "«کوئی جان دوسرے کا بوجھ نہیں اٹھاتی»", "«دین میں کوئی جبر نہیں»"], "«اے لوگو، ہم نے تمہیں ایک مرد اور ایک عورت سے پیدا کیا… بے شک تم میں سب سے معزز اللہ کے نزدیک وہ ہے جو سب سے زیادہ متقی ہے۔»"),
"sira_244": ("بیعتِ عقبہ ثانیہ، اہلِ یثرب کے ساتھ فیصلہ کن ملاقات، میں کتنے لوگ شریک ہوئے؟", ["ستر سے زائد افراد کا ایک وفد", "تین", "دس", "پانچ سو"], "بیعتِ عقبہ ثانیہ میں یثرب کے ستر سے زائد مردوں اور عورتوں کا وفد جمع ہوا۔"),
"sira_245": ("بیعتِ عقبہ کے موقع پر نبی ﷺ نے اہلِ یثرب میں کتنے نقیب (ذمہ دار سردار) مقرر کروائے؟", ["بارہ", "چار", "سات", "بیس"], "بارہ نقیب چنے گئے تاکہ وہ یثرب کے وفد کے گروہوں کی نمائندگی کریں اور ان کی بیعت کے ذمہ دار ہوں۔"),
"sira_246": ("ہجرت کے بعد مدینہ نے کون سا نام اختیار کیا؟", ["مدینۃ النبی ﷺ", "یثرب", "صرف طیبہ", "القریٰ"], "یثرب نے «مدینۃ النبی ﷺ» کا نام لیا، جو مختصر ہو کر «المدینہ» ہو گیا۔"),
"sira_247": ("کس خلیفہ نے قرآن کے سرکاری نسخے تیار کروا کر صوبوں میں بھیجے؟", ["عثمان بن عفان", "ابو بکر", "عمر", "علی"], "ابو بکر نے متن جمع کروایا؛ عثمان نے سرکاری نسخے تیار کروا کر بڑے شہروں میں بھیجے۔"),
"sira_248": ("قرآن نبی ﷺ پر کس زبان میں نازل ہوا؟", ["عربی میں", "آرامی میں", "فارسی میں", "یونانی میں"], "قرآن واضح عربی زبان میں نازل ہوا، جو نبی ﷺ کی اپنی قوم کی زبان تھی۔"),
"sira_249": ("نبی ﷺ نے کس صحابی کو بحرین بھیجا، جو وہاں کا مال لے کر لوٹے؟", ["ابو عبیدہ بن الجراح", "بلال", "انس بن مالک", "ابو ذر"], "ابو عبیدہ بن الجراح، جو «امینِ امت» کہلاتے ہیں، بحرین سے وہاں کا مال لے کر لوٹے۔"),
"sira_250": ("اسلامی تقویم کے آغاز کی نشاندہی کون سا واقعہ کرتا ہے؟", ["مکہ سے مدینہ کی طرف ہجرت", "نبی ﷺ کی ولادت", "پہلی وحی", "فتحِ مکہ"], "ہجری تقویم کا آغاز سالِ ہجرت سے ہوتا ہے، اور یہ فیصلہ عمر کے دورِ خلافت میں کیا گیا۔"),
}
